installer-gui-script.script:
function check_not_installed() {
    // Наявність застосунку — єдина ознака, на яку можна спертися до
    // розпакування: bundle id в системі з'являється лише після першого
    // запуску, а нам треба відповісти ще на вітальному екрані.
    if (system.files.fileExistsAtPath("/Applications/BarhandlerManager.app")) {
        my.result.title = "Device Handler вже встановлено";
        my.result.message = "Оновити його можна кнопкою «Оновити» на сторінці http://localhost:9999, " +
            "видалити — кнопкою «Видалити менеджер» там само.\n\n" +
            "Якщо копія зламана: спершу видаліть її з дашборда, потім запустіть цей інсталятор знову.";
        my.result.type = "Fatal";
        return false;
    }
    return true;
}
